import rcb_dtb,numpy as np
from scipy.spatial.transform import Rotation
from PIL import Image
s=rcb_dtb.Session('/app/instance.json',enable_render=True);m,d=s.model,s.data; bid=m.body('palmworld').id
# IK helper body Cartesian
def solve(startq,targetp,targetR):
 d.qpos[s._jq]=startq;s.mj.mj_forward(m,d)
 armq=s._jq[:7];ad=s._jv[:7]
 for it in range(100):
  p=d.xpos[bid].copy();R=d.xmat[bid].reshape(3,3).copy(); ep=targetp-p;er=Rotation.from_matrix(targetR@R.T).as_rotvec();err=np.r_[ep,er]
  if np.linalg.norm(ep)<.0005 and np.linalg.norm(er)<.005:break
  jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));s.mj.mj_jacBody(m,d,jp,jr,bid);J=np.vstack((jp[:,ad],jr[:,ad]));dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-4,err);d.qpos[armq]+=np.clip(dq,-.08,.08);d.qpos[armq]=np.clip(d.qpos[armq],s.lower[:7],s.upper[:7]);s.mj.mj_forward(m,d)
 return d.qpos[armq].copy(),it,np.linalg.norm(targetp-d.xpos[bid])
def grip(q,amt=1.):
 x=q.copy()
 vals={'thumb_CMC_FE':.6*amt,'thumb_MCP_FE':1.1*amt,'thumb_IP':.7*amt,
 'index_MCP_FE':1.15*amt,'index_PIP':1.15*amt,'index_DIP':.5*amt,
 'middle_MCP_FE':1.15*amt,'middle_PIP':1.15*amt,'middle_DIP':.5*amt,
 'ring_MCP_FE':1.15*amt,'ring_PIP':1.15*amt,'ring_DIP':.5*amt,
 'pinky_CMC':.4*amt,'pinky_MCP_FE':1.15*amt,'pinky_PIP':1.15*amt,'pinky_DIP':.5*amt}
 for i,n in enumerate(rcb_dtb.JOINT_NAMES[7:]):
  short=n.replace('palmleft_','')
  if short in vals:x[i+7]=vals[short]
 return np.clip(x,s.lower,s.upper)
q0=s.state()['q'].copy();p0=d.xpos[bid].copy();R0=d.xmat[bid].reshape(3,3).copy()
targetp=p0+np.array([-.02,.02,-.11]); qa,it,err=solve(q0,targetp,R0); print('IK',qa,it,err,targetp)
# move approach open over 70 steps
for k in range(70):
 tg=q0.copy(); f=min(1,(k+1)/60);tg[:7]=q0[:7]+f*(qa-q0[:7]); p=s.step(tg)
 if k%10==0 or k==69: print('approach',k,s.state()['object_pos'],s.state()['palm_pos'],s.goal_distance(),p['reached'])
qactual=s.state()['q'].copy(); print('tips open')
for name in ['thumb','index','middle','ring','pinky']:
 b=m.body('palmleft_'+name+'_DP').id;print(name,d.xpos[b])
qgr=grip(s.targets,1)
for k in range(50):
 f=min(1,(k+1)/30);tg=s.targets.copy();tg[7:]=s.targets[7:]+f*(qgr[7:]-s.targets[7:]);p=s.step(tg)
 if k%10==0 or k==49: print('close',k,s.state()['object_pos'],s.goal_distance(),p['reached'])
print('tips closed')
for name in ['thumb','index','middle','ring','pinky']:
 b=m.body('palmleft_'+name+'_DP').id;print(name,d.xpos[b])
print('contacts')
for i in range(d.ncon):
 c=d.contact[i];g1=mujoco_name=s.mj.mj_id2name(m,s.mj.mjtObj.mjOBJ_GEOM,c.geom1);g2=s.mj.mj_id2name(m,s.mj.mjtObj.mjOBJ_GEOM,c.geom2)
 if 'object_object' in str(g1) or 'object_object' in str(g2):print(g1,g2,c.dist,c.pos)
# lift target with held hand orientation, plus .12 z
pnow=d.xpos[bid].copy();Rnow=d.xmat[bid].reshape(3,3).copy();qactual=s.state()['q'].copy();q_lift,it,err=solve(qactual[:7],pnow+[0,0,.12],Rnow);print('lift IK',q_lift,it,err)
qstart=s.targets.copy();
for k in range(100):
 f=min(1,(k+1)/80);tg=qstart.copy();tg[:7]=qstart[:7]+f*(q_lift-qstart[:7]);p=s.step(tg)
 if k%10==0 or k==99: print('lift',k,s.state()['object_pos'],s.state()['object_quat_wxyz'],s.goal_distance(),p['reached'])
Image.fromarray(s.render_grid()).save('/app/output/grasp_probe.png')
