def ikpath(targetp,angle=-np.pi/2):
 d.qpos[s._jq]=qinit;s.mj.mj_forward(m,d)
 def ik(pos,Rt,n=100):
  for i in range(n):
   p=d.xpos[bid].copy();R=d.xmat[bid].reshape(3,3).copy();ep=pos-p;er=Rotation.from_matrix(Rt@R.T).as_rotvec();
   if np.linalg.norm(ep)<.0006 and np.linalg.norm(er)<.003:break
   jp=np.zeros((3,m.nv));jr=np.zeros((3,m.nv));s.mj.mj_jacBody(m,d,jp,jr,bid);J=np.vstack((jp[:,ad],jr[:,ad]));dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*3e-4,np.r_[ep,er]);d.qpos[armq]+=np.clip(dq,-.05,.05);d.qpos[armq]=np.clip(d.qpos[armq],s.lower[:7],s.upper[:7]);s.mj.mj_forward(m,d)
  return np.linalg.norm(pos-d.xpos[bid]),np.linalg.norm(Rotation.from_matrix(Rt@d.xmat[bid].reshape(3,3).T).as_rotvec())
 for a in np.linspace(0,1,21)[1:]:ik(pinit*(1-a)+targetp*a,Rinit,100)
 for a in np.linspace(0,1,19)[1:]:ik(targetp,Rotation.from_rotvec([0,0,angle*a]).as_matrix()@Rinit,100)
 return d.qpos[armq].copy(),d.xpos[bid].copy(),d.xmat[bid].reshape(3,3).copy()
def tips(qa,vals):
 d.qpos[s._jq]=qinit;d.qpos[armq]=qa
 for i,n in enumerate(rcb_dtb.JOINT_NAMES[7:]):
  nm=n.replace('palmleft_','');d.qpos[s._jq[i+7]]=vals.get(nm,0)
 s.mj.mj_forward(m,d)
 return np.array([d.xpos[m.body('palmleft_'+nm+'_DP').id].copy() for nm in ['thumb','index','middle','ring','pinky']])
vals={'thumb_CMC_FE':.8,'thumb_MCP_FE':.8,'thumb_IP':.8,'index_MCP_FE':1.15,'index_PIP':1.15,'index_DIP':.5,'middle_MCP_FE':1.15,'middle_PIP':1.15,'middle_DIP':.5,'ring_MCP_FE':1.15,'ring_PIP':1.15,'ring_DIP':.5,'pinky_CMC':.4,'pinky_MCP_FE':1.15,'pinky_PIP':1.15,'pinky_DIP':.5}
for p in [[.12,.0,.62],[.15,.0,.62],[.17,.0,.62],[.12,.02,.60],[.15,.02,.60]]:
 qa,pa,R=ikpath(np.array(p)); print('\nrequest',p,'actual',pa,'q',np.round(qa,2)); print('closed tips',np.round(tips(qa,vals),3))
